From af1d0c3d80e16c1c27da8070175137eca90bbc78 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 19:46:34 +0100
Subject: [PATCH] applets/taskmanager: let windows be on several desktops from
 the menu

The task context menu could only move a window to one desktop, unlike
KWin's window menu. Desktops are now checkboxes that add or remove the
window like there, followed by "Move to" items for a single desktop.

BUG: 491306
---
 applets/taskmanager/qml/ContextMenu.qml | 41 ++++++++++++++++++++-----
 1 file changed, 34 insertions(+), 7 deletions(-)

diff --git a/applets/taskmanager/qml/ContextMenu.qml b/applets/taskmanager/qml/ContextMenu.qml
index fe837049fc..d70f92b2ce 100644
--- a/applets/taskmanager/qml/ContextMenu.qml
+++ b/applets/taskmanager/qml/ContextMenu.qml
@@ -290,7 +290,7 @@ PlasmaExtras.Menu {

         enabled: visible

-        text: i18nc("action:inmenu", "Move to &Desktop")
+        text: i18nc("action:inmenu", "&Desktops")
         icon: "virtual-desktops"

         readonly property Connections virtualDesktopsMenuConnections: Connections {
@@ -348,9 +348,14 @@ PlasmaExtras.Menu {
                     return menu.visualParent && menu.get(TaskManager.AbstractTasksModel.IsOnAllVirtualDesktops);
                 });
                 menuItem.clicked.connect(() => {
-                    tasksModel.requestVirtualDesktops(menu.modelIndex, []);
+                    if (!menu.get(TaskManager.AbstractTasksModel.IsOnAllVirtualDesktops)) {
+                        tasksModel.requestVirtualDesktops(menu.modelIndex, []);
+                        return;
+                    }
+                    TaskManagerApplet.TaskTools.foreachChildTask((childIndex) => {
+                        tasksModel.requestVirtualDesktops(childIndex, [virtualDesktopInfo.currentDesktopByScreenGeometry(tasksModel.data(childIndex, TaskManager.AbstractTasksModel.ScreenGeometry))]);
+                    }, menu.modelIndex, tasksModel);
                 });
-                menu.backend.setActionGroup(menuItem.action);

                 menu.newSeparator(virtualDesktopsMenu);

@@ -361,10 +366,32 @@ PlasmaExtras.Menu {
                     menuItem.checked = Qt.binding((i => {
                         return () => menu.visualParent && menu.get(TaskManager.AbstractTasksModel.VirtualDesktops).indexOf(virtualDesktopInfo.desktopIds[i]) > -1;
                     })(i));
-                    menuItem.clicked.connect((i => {
-                        return () => tasksModel.requestVirtualDesktops(menu.modelIndex, [virtualDesktopInfo.desktopIds[i]]);
-                    })(i));
-                    menu.backend.setActionGroup(menuItem.action);
+                    menuItem.clicked.connect((desktopId => {
+                        return () => {
+                            let desktops = menu.get(TaskManager.AbstractTasksModel.VirtualDesktops);
+                            if (desktops.indexOf(desktopId) > -1) {
+                                desktops = desktops.filter(desktop => desktop !== desktopId);
+                            } else {
+                                desktops = desktops.concat(desktopId);
+                            }
+                            tasksModel.requestVirtualDesktops(menu.modelIndex, desktops);
+                        };
+                    })(virtualDesktopInfo.desktopIds[i]));
+                }
+
+                menu.newSeparator(virtualDesktopsMenu);
+
+                for (let i = 0; i < virtualDesktopInfo.desktopNames.length; ++i) {
+                    const onDesktops = menu.get(TaskManager.AbstractTasksModel.VirtualDesktops);
+                    if (onDesktops.length === 1 && onDesktops[0] === virtualDesktopInfo.desktopIds[i]) {
+                        continue;
+                    }
+
+                    menuItem = menu.newMenuItem(virtualDesktopsMenu);
+                    menuItem.text = i18nc("action:inmenu", "Move to %1", virtualDesktopInfo.desktopNames[i]);
+                    menuItem.clicked.connect((desktopId => {
+                        return () => tasksModel.requestVirtualDesktops(menu.modelIndex, [desktopId]);
+                    })(virtualDesktopInfo.desktopIds[i]));
                 }

                 menu.newSeparator(virtualDesktopsMenu);
-- 
